<script setup lang="ts">
import { useRoute } from 'vue-router';
import { onMounted, ref } from 'vue';
import DashboardLayout from '@/layouts/DashboardLayout.vue';
import ApiAlert from '@/components/ApiAlert.vue';
import { api, errorMessage } from '@/api/client';
import type { ApiResponse, DirectoryProfile, Pagination } from '@/types/api';
const alumni = ref<DirectoryProfile[]>([]), selected = ref<DirectoryProfile | null>(null), pagination = ref<Pagination | null>(null);
const route = useRoute();
const search = ref(typeof route.query.search === 'string' ? route.query.search.slice(0, 150) : ''), year = ref(''), page = ref(1), loading = ref(false), error = ref(''), detailLoading = ref(false);
async function load() { loading.value = true; error.value = ''; selected.value = null; try { const response = await api.get<ApiResponse<DirectoryProfile[]>>('/alumni/directory', { params: { page: page.value, limit: 12, search: search.value || undefined, graduationYear: year.value || undefined } }); alumni.value = response.data.data; pagination.value = response.data.pagination; } catch (e) { error.value = errorMessage(e); } finally { loading.value = false; } }
async function detail(id: string) { error.value = ''; detailLoading.value = true; try { selected.value = (await api.get<ApiResponse<DirectoryProfile>>(`/alumni/directory/${id}`)).data.data; } catch (e) { error.value = errorMessage(e); } finally { detailLoading.value = false; } }
function filter() { page.value = 1; void load(); }
onMounted(load);
</script>
<template><DashboardLayout><section class="mx-auto max-w-6xl space-y-6 p-5 lg:p-10"><h1 class="text-h1">Alumni directory</h1><p class="text-secondary">Connect with approved, activated members. Private contact and verification information is excluded.</p><ApiAlert :message="error"/><form class="flex flex-wrap items-end gap-4 border bg-white p-5" @submit.prevent="filter"><div class="flex-1"><label for="directory-search" class="field-label">Search by name</label><input id="directory-search" v-model.trim="search" class="field-input" maxlength="150"></div><div><label for="directory-year" class="field-label">Graduation year</label><input id="directory-year" v-model="year" class="field-input" type="number" min="1900" :max="new Date().getFullYear()" placeholder="All years"></div><button class="primary-button" :disabled="loading">Search directory</button></form><p v-if="loading" role="status">Loading alumni…</p><div v-else class="grid gap-5 sm:grid-cols-2 xl:grid-cols-3"><article v-for="person in alumni" :key="person.id" class="space-y-3 border bg-white p-6"><img v-if="person.profileImage" :src="person.profileImage" :alt="person.fullName" referrerpolicy="no-referrer" class="h-20 w-20 rounded-full object-cover"><h2 class="text-h2">{{ person.fullName }}</h2><p v-if="person.graduationYear" class="text-sm">Class of {{ person.graduationYear }}</p><p v-if="person.occupation">{{ person.occupation }}</p><p v-if="person.location" class="text-secondary">{{ person.location }}</p><button class="underline" :disabled="detailLoading" @click="detail(person.id)">View alumni profile</button></article><p v-if="!alumni.length">No matching alumni members.</p></div><nav class="flex flex-wrap items-center gap-4" aria-label="Alumni directory pages"><button class="secondary-button" :disabled="page <= 1 || loading" @click="page--; load()">Previous</button><span>Page {{ page }} · {{ pagination?.total ?? 0 }} members</span><button class="secondary-button" :disabled="!pagination || page >= pagination.totalPages || loading" @click="page++; load()">Next</button></nav><section v-if="selected" class="space-y-4 border bg-white p-6" aria-live="polite"><div class="flex justify-between"><h2 class="text-h2">{{ selected.fullName }}</h2><button class="underline" @click="selected = null">Close profile</button></div><p v-if="selected.graduationYear">Class of {{ selected.graduationYear }}</p><p>{{ [selected.occupation, selected.location].filter(Boolean).join(' · ') }}</p><p class="whitespace-pre-wrap">{{ selected.bio || 'This member has not added a biography yet.' }}</p></section></section></DashboardLayout></template>
